inline constexpr std::string_view kCommandDefinitionsJSON = R"fly_json([{"id":"spawn-tab","title":"New Blank Tab","desc":"Open a fresh tab using the configured search engine","details":"Opens Fly's new tab page in a new tab of the current workspace, where you can type an address or search with the default engine.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"spawn-tab","keywords":["tab","open","new","create","blank"]},{"id":"toggle-address","title":"Toggle Floating Address Bar","desc":"Open floating address bar for URL entry and search engine aliases","details":"Displays the modal address bar supporting direct URL routing, query auto-completion, and bang search engine aliases such as !w for Wikipedia.","tip":"Type ! to browse active search aliases or paste raw URLs to navigate instantly.","category":"Tabs & Navigation","actionId":"toggle-address","keywords":["url","address","search","goto","navigate","location"]},{"id":"toggle-dashboard","title":"Toggle Workspace Dashboard","desc":"Full-page tree view of all workspaces, tabs, and windows","details":"Renders an expansive visual hierarchy of every workspace, active tab, and page across the session with bulk management controls.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-dashboard","keywords":["workspace","tree","tabs","all","overview","dashboard"]},{"id":"toggle-history","title":"Toggle Actionable History","desc":"Search, filter by domain, or purge browsing history records","details":"Opens the searchable history ledger stored locally, featuring domain-level filtering and surgical record purging.","tip":"Filter by specific domains to audit past navigation or clear privacy-sensitive sessions.","category":"Tabs & Navigation","actionId":"toggle-history","keywords":["history","recent","visited","log","purge"]},{"id":"toggle-status-bar","title":"Toggle Status & Mode Bar","desc":"Show or hide the bottom status bar displaying mode, target URL, and TLS state","details":"Shows or hides the status bar along the bottom of the window: the keyboard mode and the address of the link under the pointer on the left; zoom, extension actions, notifications, connection security, workspace and clock on the right.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-status-bar","keywords":["status","mode","bar","footer","url preview","toggle","bottom"]},{"id":"toggle-clock","title":"Toggle Clock & Date Display","desc":"Show or hide the live clock in the status bar and sidebar","details":"Toggles the real-time clock widget displaying local date and time in the bottom status bar and vertical sidebar.","tip":"Click on the clock at any time to cycle between date and time, time only, and seconds.","category":"Preferences & System","actionId":"toggle-clock","keywords":["clock","time","date","watch","hours","minutes","status"]},{"id":"cycle-clock-format","title":"Cycle Clock Format (Date & Time / Time / Seconds)","desc":"Switch between date and time, compact time, or time with seconds","details":"Rotates the clock presentation mode between standard UK date and time, compact time-only, and high-precision seconds.","tip":"You can also click the clock widget directly in the status bar or sidebar.","category":"Preferences & System","actionId":"cycle-clock-format","keywords":["clock","format","seconds","time","date","cycle","switch"]},{"id":"toggle-window-controls","title":"Toggle Window Controls (Minimise, Maximise, Close)","desc":"Show or hide window action buttons in the sidebar for desktop environments","details":"Displays window management buttons at the top of the vertical sidebar. Ideal for desktop environments such as KDE or GNOME where native window buttons are hidden or disabled.","tip":"Enable this if your desktop environment hides title bars on maximised windows.","category":"Preferences & System","actionId":"toggle-window-controls","keywords":["window","controls","minimize","minimise","maximize","maximise","close","restore","buttons","kde","gnome"]},{"id":"trigger-hints","title":"Toggle Link Hints Overlay","desc":"Display letter tags over clickable links for mouse-free browsing","details":"Injects minimal letter tags over all actionable elements, hyperlinks, and inputs in the viewport to enable rapid keyboard-only navigation.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"trigger-hints","keywords":["hints","click","links","letters","vim","keyboard"]},{"id":"toggle-find","title":"Find In Page","desc":"Search for text matches within the current active webpage","details":"Opens the find bar for the active page, highlights every match and moves between them from the keyboard.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-find","keywords":["find","search","page","text","lookup"]},{"id":"reload-active-tab","title":"Reload Active Tab","desc":"Reload the current page","details":"Loads the current page again. The tab keeps its place, history and workspace.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"reload-active-tab","keywords":["reload","refresh","page","update"]},{"id":"remove-tab","title":"Close Current Tab","desc":"Close the active tab and focus the adjacent one","details":"Closes the active tab and moves focus to the nearest remaining tab.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"remove-tab","keywords":["close","remove","delete","tab","exit"]},{"id":"toggle-pin-tab","title":"Pin / Unpin Active Tab","desc":"Pin essential tab to the top of workspace or unpin it","details":"Pinned tabs stay anchored at the top of the tab list, are protected from accidental closure, and are exempted from automatic suspension.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-pin-tab","keywords":["pin","unpin","sticky","essential","lock","tab"]},{"id":"reset-zoom","title":"Reset Site Zoom Level","desc":"Restore webpage zoom magnification back to 100% default","details":"Restores 100% zoom for this site in every open tab and clears its saved zoom preference.","tip":"Quickly recover standard layout proportions if a page was accidentally zoomed.","category":"Tabs & Navigation","actionId":"reset-zoom","keywords":["zoom","scale","magnify","size","100%"]},{"id":"focus-sidebar","title":"Toggle Sidebar Focus","desc":"Move focus between the sidebar and the active page","details":"Opens the sidebar without focusing a tab or button. Use Tab or the arrow keys to navigate. Run again to return to the page and collapse an unpinned sidebar. A pinned sidebar stays open.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"focus-sidebar","keywords":["sidebar","tabs","focus","list"]},{"id":"focus-nav-buttons","title":"Focus Navigation Buttons","desc":"Cycle focus across Back, Forward, Sidebar, Split, and Menu buttons","details":"Places keyboard focus onto the primary toolbar buttons, allowing navigation using left and right arrow keys.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"focus-nav-buttons","keywords":["buttons","back","forward","top","controls"]},{"id":"focus-webview","title":"Focus Active Page","desc":"Return keyboard and input focus to the active webpage","details":"Moves keyboard focus from the sidebar or a panel back into the active page.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"focus-webview","keywords":["focus","page","content"]},{"id":"toggle-sidebar-pin","title":"Toggle Sidebar Expansion (Pin / Unpin)","desc":"Pin sidebar open or auto-shrink to 36px strip expanding on hover","details":"Configures auto-collapse behaviour: when unpinned, the sidebar shrinks to 36px and slides out smoothly when your cursor hovers nearby.","tip":"Unpin for an immersive browsing canvas that leaves controls within easy reach.","category":"Tabs & Navigation","actionId":"toggle-zen-mode","keywords":["pin","lock","unpin","autohide","strip"]},{"id":"toggle-split-vertical","title":"Toggle Dual-Split View (Side-by-Side)","desc":"Show two tabs side by side in equal columns","details":"Splits the active viewport into two concurrent columns, allowing side-by-side comparison, documentation reading, or multitasking.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Split View","actionId":"toggle-split","keywords":["split","dual","side","vertical","columns","multitask"]},{"id":"toggle-split-horizontal","title":"Toggle Dual-Split View (Stacked)","desc":"Show two tabs stacked in top and bottom rows","details":"Divides the viewport horizontally into stacked top and bottom panes, ideal for viewing reference materials above a web console.","tip":"Useful on vertical monitors or when referencing notes above an active page.","category":"Split View","actionId":"toggle-split-horizontal","keywords":["split","horizontal","stacked","rows","top","bottom"]},{"id":"cycle-split-orientation","title":"Cycle Split View Orientation","desc":"Switch active dual-split layout between side-by-side and stacked","details":"Switches the split between side-by-side columns and stacked rows without reloading either page.","tip":"Adapt your workspace layout on the fly depending on webpage content.","category":"Split View","actionId":"cycle-split-orientation","keywords":["split","rotate","cycle","layout","orientation"]},{"id":"switch-split-focus","title":"Switch Split Pane Focus","desc":"Move active keyboard and scroll focus to the opposite split pane","details":"Switches the active input target between primary and secondary split panes without needing cursor clicks.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Split View","actionId":"switch-split-focus","keywords":["split","focus","pane","switch","alternate"]},{"id":"swap-split-panes","title":"Swap Split Panes","desc":"Exchange positions of the primary and secondary split panes","details":"Reverses the left/right or top/bottom layout ordering of the active dual panes whilst maintaining their states.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Split View","actionId":"swap-split-panes","keywords":["split","swap","flip","reverse","exchange"]},{"id":"close-split-view","title":"Close Split View","desc":"Exit dual-split mode and return to standard single tab viewport","details":"Ends the split view and returns to a single page.","tip":"Quickly return to single-task focus once your comparison work is finished.","category":"Split View","actionId":"close-split-view","keywords":["split","close","exit","single"]},{"id":"hibernate-tabs","title":"Suspend Inactive Tabs","desc":"Pause eligible background pages without unloading them","details":"Freezes eligible pages in memory, preserving their document and JavaScript state. Busy pages remain running.","tip":"Suspension saves CPU and battery; pages remain in memory.","category":"Performance & Memory","actionId":"hibernate-tabs","keywords":["pause","background","suspend","battery"]},{"id":"wake-all-tabs","title":"Resume Tabs in Workspace","desc":"Resume suspended pages in the active workspace without reloading","details":"Resumes existing pages. Tabs not yet opened since startup remain unloaded.","tip":"Use this when resuming work on a project after an extended idle period.","category":"Performance & Memory","actionId":"wake-all-tabs","keywords":["resume","background","tabs","workspace"]},{"id":"toggle-bookmarks","title":"Bookmarks Manager","desc":"Open your saved bookmarks","details":"Displays your saved bookmarks with filtering and deletion controls.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-bookmarks","keywords":["bookmarks","saved","favorites"]},{"id":"add-bookmark","title":"Bookmark Current Page","desc":"Save the active page to your bookmarks","details":"Saves the active tab's title and address to your bookmarks, shared by every workspace.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"add-bookmark","keywords":["bookmark","save","favorite","page","add"]},{"id":"toggle-downloads","title":"Toggle Downloads Shelf","desc":"Slide out bottom downloads drawer with speed and file links","details":"Opens the download shelf showing real-time progress bars, transfer rates, destination paths, and file opening actions.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-downloads","keywords":["downloads","files","shelf","drawer"]},{"id":"toggle-devtools","title":"Toggle Developer Tools","desc":"Inspect webpage DOM elements, console logs, and network traffic","details":"Opens or closes Chromium's developer tools for the active page to inspect elements and debug scripts.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-devtools","keywords":["devtools","inspect","console","debug","elements"]},{"id":"toggle-global-media","title":"Toggle Global Media Playback","desc":"Play or pause audio and video streams across all workspaces","details":"Pauses the audio or video playing in any tab, or resumes what was paused, so background audio can be controlled from anywhere.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-global-media","keywords":["media","play","pause","music","video","stream"]},{"id":"toggle-tab-audio-mute","title":"Toggle Tab Audio Mute","desc":"Mute or unmute audio output for the active tab","details":"Toggles audio mute state for the active tab without pausing video or audio playback.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-tab-audio-mute","keywords":["mute","audio","sound","volume","silence","unmute","speaker"]},{"id":"toggle-global-audio-mute","title":"Toggle Global Audio Mute","desc":"Mute or unmute audio output across all tabs and workspaces","details":"Silences all web audio and media output across all open tabs simultaneously.","tip":"Press M in NORMAL mode to toggle global audio mute.","category":"Tools","actionId":"toggle-global-audio-mute","keywords":["mute","audio","sound","volume","silence","global","all","panictab"]},{"id":"open-scripts-dir","title":"Open User Scripts Directory","desc":"Open the scripts folder of your profile in the file manager","details":"Opens <profile>/scripts in your file manager. Fly runs the .user.js files there in matching pages.","tip":"Drop .user.js files here to automate page behaviours and customise web applications.","category":"User Scripts & Styles","actionId":"open-scripts-dir","keywords":["scripts","userscript","tampermonkey","js","javascript","folder","directory"]},{"id":"open-styles-dir","title":"Open User Styles Directory","desc":"Open the styles folder of your profile in the file manager","details":"Opens <profile>/styles in your file manager. Fly applies the .user.css files there to matching pages.","tip":"Drop .user.css files here to create dark themes or tweak styling for any website.","category":"User Scripts & Styles","actionId":"open-styles-dir","keywords":["styles","userstyle","stylish","css","folder","directory","theme"]},{"id":"reload-user-content","title":"Reload User Scripts and Styles","desc":"Hot-reload all custom user scripts and stylesheet injections","details":"Reads the scripts and styles folders again and applies the changes in every workspace.","tip":"Run this command immediately after saving CSS or JS changes to preview them live.","category":"User Scripts & Styles","actionId":"reload-user-content","keywords":["reload","refresh","inject","userscripts","userstyles"]},{"id":"toggle-private-mode","title":"Toggle Private Browsing Mode","desc":"Open a private window, or close the private windows","details":"Opens a private window whose cookies, cache and history are discarded when it closes. Run it from a private window to close the private windows.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Preferences & System","actionId":"toggle-private-mode","keywords":["private","incognito","privacy","partition"]},{"id":"test-google-signin","title":"Test Clean Google Sign-In Flow","desc":"Open Google Sign-In in a private window with no saved sign-in","details":"Opens accounts.google.com in a private window that shares no cookies or tokens with your workspaces, to check that Google accepts the sign-in.","tip":"Use this diagnostic action to audit whether Google authentication works without risking your active workspace logins.","category":"Preferences & System","actionId":"test-google-signin","keywords":["google","auth","signin","login","test","clean","diagnostic"]},{"id":"toggle-reader-view","title":"Toggle Reader View on Active Tab","desc":"Distil web article into clean, distraction-free reading layout","details":"Extracts article text, byline, and media using in-engine Mozilla Readability with custom themes and typography.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Web Interaction","actionId":"toggle-reader-view","keywords":["reader","view","read","article","distill","clean","typography","book"]},{"id":"toggle-theme","title":"Toggle Colour Theme (Dark / Light)","desc":"Switch the interface between dark and light","details":"Switches Fly between its dark and light themes. Websites with their own dark mode follow when Match websites to the theme is on in Preferences.","tip":"Quickly adapt screen contrast when working late or in brightly lit environments.","category":"Preferences & System","actionId":"toggle-theme","keywords":["theme","dark","light","mode","colour","color"]},{"id":"toggle-menu-bar","title":"Open Native Settings Menu","desc":"Open the native browser settings menu","details":"Opens the native menu containing browser settings and application controls.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Preferences & System","actionId":"toggle-menu-bar","keywords":["menu","bar","top","native","window"]},{"id":"check-for-updates","title":"Check for Updates","desc":"Check GitHub Releases for newer Fly versions and release notes","details":"Asks GitHub whether a newer Fly release exists. When one does, Fly can install it in place and restart with your tabs, or link to its release page.","tip":"Release candidates are never offered; only stable releases are.","category":"Preferences & System","actionId":"check-for-updates","keywords":["update","upgrade","version","release","github","check"]},{"id":"show-whats-new","title":"Show What's New","desc":"Open release highlights for this version in a new tab","details":"Opens the offline release highlights page covering recent features, performance improvements, and security updates.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Preferences & System","actionId":"show-whats-new","keywords":["whats","new","update","changelog","release","notes","version"]},{"id":"open-diagnostics","title":"Open Diagnostics & Health Hub","desc":"View system health, memory utilisation, logs, and generate sanitised bug reports","details":"Opens Diagnostics: system and runtime versions, processes and memory, the in-memory event log, and a sanitised report to copy into an issue.","tip":"Zero telemetry: all diagnostic statistics remain 100% local to your machine.","category":"Preferences & System","actionId":"open-diagnostics","keywords":["diagnostics","diag","health","bug","report","issue","memory","logs","system"]},{"id":"toggle-diagnostics-recording","title":"Toggle Diagnostics Recording (In-Memory)","desc":"Enable or disable local in-memory diagnostic event logging (OFF by default)","details":"Turns the local in-memory log of page errors and navigation warnings on or off. Nothing is sent over the network.","tip":"Toggle recording on when reproducing issues before generating an issue report.","category":"Preferences & System","actionId":"toggle-diagnostics-recording","keywords":["diagnostics","recording","telemetry","privacy","logs","debug"]}])fly_json";
